import { google, sheets_v4 } from "googleapis";

export const RESERVATION_SHEET_NAMES = ["国内", "韓国", "台湾"] as const;
export type ReservationSheetName = typeof RESERVATION_SHEET_NAMES[number];

export type ReservationRecord = {
  sheetName: ReservationSheetName;
  rowNumber: number;
  values: Record<string, string>;
};

let cachedSheetsClient: sheets_v4.Sheets | null = null;

async function getSheetsClient(): Promise<sheets_v4.Sheets> {
  if (cachedSheetsClient) {
    return cachedSheetsClient;
  }
  const email = process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL;
  const key = process.env.GOOGLE_SERVICE_ACCOUNT_KEY;
  if (!email || !key) {
    throw new Error("Google Service Account credentials are not set in environment variables.");
  }
  const auth = new google.auth.JWT({
    email,
    key: key.replace(/\\n/g, "\n"),
    scopes: ["https://www.googleapis.com/auth/spreadsheets"],
  });
  cachedSheetsClient = google.sheets({ version: "v4", auth });
  return cachedSheetsClient;
}

async function getHeaderRow(sheetName: ReservationSheetName): Promise<string[]> {
  const sheets = await getSheetsClient();
  const spreadsheetId = process.env.GOOGLE_SHEET_ID;
  if (!spreadsheetId) {
    throw new Error("GOOGLE_SHEET_ID is not set in environment variables.");
  }
  const response = await sheets.spreadsheets.values.get({
    spreadsheetId,
    range: `${sheetName}!1:1`,
  });
  const rows = response.data.values;
  if (!rows || rows.length === 0) {
    return [];
  }
  return (rows[0] as unknown[]).map((cell) => String(cell ?? ""));
}

function columnIndexToA1(index: number): string {
  let temp = index + 1;
  let letter = "";
  while (temp > 0) {
    const remainder = (temp - 1) % 26;
    letter = String.fromCharCode(65 + remainder) + letter;
    temp = Math.floor((temp - 1) / 26);
  }
  return letter;
}

async function ensureStatusColumns(sheetName: ReservationSheetName): Promise<void> {
  const headers = await getHeaderRow(sheetName);
  const required = ["ステータス", "確定日時", "Meetリンク"];
  const missing = required.filter((col) => !headers.includes(col));
  if (missing.length === 0) {
    return;
  }
  const sheets = await getSheetsClient();
  const spreadsheetId = process.env.GOOGLE_SHEET_ID;
  if (!spreadsheetId) {
    throw new Error("GOOGLE_SHEET_ID is not set in environment variables.");
  }
  const newHeaders = [...headers, ...missing];
  const startCol = columnIndexToA1(0);
  const endCol = columnIndexToA1(newHeaders.length - 1);
  const range = `${sheetName}!${startCol}1:${endCol}1`;
  await sheets.spreadsheets.values.update({
    spreadsheetId,
    range,
    valueInputOption: "USER_ENTERED",
    requestBody: {
      values: [newHeaders],
    },
  });
}

export async function listPendingReservations(): Promise<ReservationRecord[]> {
  const spreadsheetId = process.env.GOOGLE_SHEET_ID;
  if (!spreadsheetId) {
    throw new Error("GOOGLE_SHEET_ID is not set in environment variables.");
  }
  const sheets = await getSheetsClient();
  const records: ReservationRecord[] = [];

  for (const sheetName of RESERVATION_SHEET_NAMES) {
    await ensureStatusColumns(sheetName);
    const headers = await getHeaderRow(sheetName);
    const response = await sheets.spreadsheets.values.get({
      spreadsheetId,
      range: `${sheetName}!A2:Z`,
    });
    const rows = response.data.values;
    if (!rows || rows.length === 0) {
      continue;
    }

    const statusIndex = headers.indexOf("ステータス");

    rows.forEach((row, rowIndex) => {
      const rowNumber = rowIndex + 2;
      const values: Record<string, string> = {};
      headers.forEach((header, colIndex) => {
        values[header] = row[colIndex] !== undefined && row[colIndex] !== null ? String(row[colIndex]) : "";
      });

      const status = statusIndex !== -1 && row[statusIndex] !== undefined && row[statusIndex] !== null
        ? String(row[statusIndex]).trim()
        : "";

      if (status === "" || status === "未確定") {
        records.push({
          sheetName,
          rowNumber,
          values,
        });
      }
    });
  }

  return records;
}

export async function confirmReservation(
  sheetName: ReservationSheetName,
  rowNumber: number,
  confirmedDateTime: string,
  meetLink: string
): Promise<void> {
  await ensureStatusColumns(sheetName);
  const headers = await getHeaderRow(sheetName);
  const statusIndex = headers.indexOf("ステータス");
  const confirmedDateTimeIndex = headers.indexOf("確定日時");
  const meetLinkIndex = headers.indexOf("Meetリンク");

  if (statusIndex === -1 || confirmedDateTimeIndex === -1 || meetLinkIndex === -1) {
    throw new Error("Required columns not found after ensureStatusColumns.");
  }

  const spreadsheetId = process.env.GOOGLE_SHEET_ID;
  if (!spreadsheetId) {
    throw new Error("GOOGLE_SHEET_ID is not set in environment variables.");
  }
  const sheets = await getSheetsClient();

  const minCol = Math.min(statusIndex, confirmedDateTimeIndex, meetLinkIndex);
  const maxCol = Math.max(statusIndex, confirmedDateTimeIndex, meetLinkIndex);
  const startColA1 = columnIndexToA1(minCol);
  const endColA1 = columnIndexToA1(maxCol);
  const range = `${sheetName}!${startColA1}${rowNumber}:${endColA1}${rowNumber}`;

  const rowValues: string[] = new Array(maxCol - minCol + 1).fill("");
  rowValues[statusIndex - minCol] = "確定";
  rowValues[confirmedDateTimeIndex - minCol] = confirmedDateTime;
  rowValues[meetLinkIndex - minCol] = meetLink;

  await sheets.spreadsheets.values.update({
    spreadsheetId,
    range,
    valueInputOption: "USER_ENTERED",
    requestBody: {
      values: [rowValues],
    },
  });
}

export async function cancelReservation(
  sheetName: ReservationSheetName,
  rowNumber: number
): Promise<void> {
  await ensureStatusColumns(sheetName);
  const headers = await getHeaderRow(sheetName);
  const statusIndex = headers.indexOf("ステータス");

  if (statusIndex === -1) {
    throw new Error("Status column not found after ensureStatusColumns.");
  }

  const spreadsheetId = process.env.GOOGLE_SHEET_ID;
  if (!spreadsheetId) {
    throw new Error("GOOGLE_SHEET_ID is not set in environment variables.");
  }
  const sheets = await getSheetsClient();
  const colA1 = columnIndexToA1(statusIndex);
  const range = `${sheetName}!${colA1}${rowNumber}`;

  await sheets.spreadsheets.values.update({
    spreadsheetId,
    range,
    valueInputOption: "USER_ENTERED",
    requestBody: {
      values: [["キャンセル"]],
    },
  });
}
